    ts = df['timestamp\t']
    for t in ts.fillna('<NA>'):
        p = re.sub(r'\d', '#', str(t))
        allpats.setdefault(p, []).append((fid, t))
for p, v in sorted(allpats.items(), key=lambda x: -len(x[1])):
    print(f'{p!r:35} n={len(v):5} e.g. {v[0]}')
